-- Migración 004: cambiar todas las columnas GENERATED ALWAYS AS IDENTITY
-- a GENERATED BY DEFAULT ON NULL AS IDENTITY para compatibilidad con
-- APEX form processing (formAutoRowProcessing incluye el PK con NULL en el
-- INSERT, lo que ORA-32795 rechaza en modo ALWAYS).
-- Ejecutar como usuario ESTIMADOR contra FREEPDB1

ALTER TABLE CLIENTES                            MODIFY CLIENTE_ID                       GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE CONTACTOS_CLIENTE                   MODIFY CONTACTO_ID                      GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE PAISES                              MODIFY PAIS_ID                          GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE PROYECTOS                           MODIFY PROYECTO_ID                      GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE VERSIONES_ESTIMACION                MODIFY VERSION_ESTIMACION_ID            GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE ELEMENTOS                           MODIFY ELEMENTO_ID                      GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE ESTIMACION_PARAMETROS_COMPLEJIDAD   MODIFY ESTIMACION_PARAM_COMPLEJIDAD_ID  GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE ESTIMACION_PARAMETROS_ETAPA_CASE    MODIFY ESTIMACION_PARAM_ETAPA_CASE_ID   GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE ESTIMACION_PARAMETROS_TIEMPO_ADICIONAL MODIFY ESTIMACION_PARAM_TIEMPO_ADIC_ID GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE LINEAS_DETALLE                      MODIFY LINEA_DETALLE_ID                 GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE PARAMETROS_COMPLEJIDAD              MODIFY PARAMETRO_COMPLEJIDAD_ID         GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE PARAMETROS_ETAPA_CASE               MODIFY PARAMETRO_ETAPA_CASE_ID          GENERATED BY DEFAULT ON NULL AS IDENTITY;
ALTER TABLE PARAMETROS_TIEMPO_ADICIONAL         MODIFY PARAMETRO_TIEMPO_ADICIONAL_ID    GENERATED BY DEFAULT ON NULL AS IDENTITY;
